DROP DATABASE IF EXISTS tienda_cartas;
CREATE DATABASE tienda_cartas CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci;
USE tienda_cartas;
CREATE TABLE Usuario(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario VARCHAR(50) NOT NULL UNIQUE,email VARCHAR(120) NOT NULL UNIQUE,telefono VARCHAR(20) UNIQUE,password VARCHAR(100) NOT NULL,fecha_registro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,rol ENUM('ADMINISTRADOR','CLIENTE') NOT NULL DEFAULT 'CLIENTE') ENGINE=InnoDB;
CREATE TABLE Direccion(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,nombre_destinatario VARCHAR(120) NOT NULL,calle VARCHAR(150) NOT NULL,numero VARCHAR(20) NOT NULL,piso VARCHAR(20),ciudad VARCHAR(80) NOT NULL,provincia VARCHAR(80) NOT NULL,codigo_postal VARCHAR(12) NOT NULL,pais VARCHAR(80) NOT NULL,principal BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(usuario_id) REFERENCES Usuario(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE Carrito(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL UNIQUE,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES Usuario(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE Producto(id BIGINT AUTO_INCREMENT PRIMARY KEY,carta_externa_id VARCHAR(100) NOT NULL,idioma VARCHAR(10) NOT NULL,estado_carta ENUM('NUEVA','EXCELENTE','BUENA','ACEPTABLE','DANADA') NOT NULL,acabado ENUM('NORMAL','HOLO','REVERSE_HOLO') NOT NULL,precio DECIMAL(10,2) NOT NULL CHECK(precio>=0),stock INT NOT NULL CHECK(stock>=0),activo BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(carta_externa_id,idioma,estado_carta,acabado)) ENGINE=InnoDB;
CREATE TABLE DetalleCarrito(carrito_id BIGINT NOT NULL,producto_id BIGINT NOT NULL,cantidad INT NOT NULL CHECK(cantidad>0),PRIMARY KEY(carrito_id,producto_id),FOREIGN KEY(carrito_id) REFERENCES Carrito(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES Producto(id)) ENGINE=InnoDB;
CREATE TABLE Pedido(id BIGINT AUTO_INCREMENT PRIMARY KEY,comprador_id BIGINT NOT NULL,direccion_envio_id BIGINT,nombre_destinatario VARCHAR(120) NOT NULL,calle VARCHAR(150) NOT NULL,numero VARCHAR(20) NOT NULL,piso VARCHAR(20),ciudad VARCHAR(80) NOT NULL,provincia VARCHAR(80) NOT NULL,codigo_postal VARCHAR(12) NOT NULL,pais VARCHAR(80) NOT NULL,fecha_pedido DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,estado ENUM('PENDIENTE','PAGADO','PREPARANDO','ENVIADO','ENTREGADO','CANCELADO') NOT NULL DEFAULT 'PENDIENTE',subtotal DECIMAL(10,2) NOT NULL CHECK(subtotal>=0),gastos_envio DECIMAL(10,2) NOT NULL CHECK(gastos_envio>=0),total DECIMAL(10,2) NOT NULL,CHECK(total=subtotal+gastos_envio),FOREIGN KEY(comprador_id) REFERENCES Usuario(id),FOREIGN KEY(direccion_envio_id) REFERENCES Direccion(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE DetallePedido(id BIGINT AUTO_INCREMENT PRIMARY KEY,pedido_id BIGINT NOT NULL,producto_id BIGINT,carta_externa_id VARCHAR(100) NOT NULL,nombre_carta VARCHAR(150) NOT NULL,nombre_set VARCHAR(150),numero_carta VARCHAR(30),idioma VARCHAR(10) NOT NULL,estado_carta VARCHAR(20) NOT NULL,acabado VARCHAR(20) NOT NULL,cantidad INT NOT NULL CHECK(cantidad>0),precio_unitario DECIMAL(10,2) NOT NULL CHECK(precio_unitario>=0),subtotal DECIMAL(10,2) NOT NULL,CHECK(subtotal=cantidad*precio_unitario),FOREIGN KEY(pedido_id) REFERENCES Pedido(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES Producto(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE Pago(id BIGINT AUTO_INCREMENT PRIMARY KEY,pedido_id BIGINT NOT NULL,metodo ENUM('TARJETA','PAYPAL','TRANSFERENCIA') NOT NULL,estado ENUM('PENDIENTE','COMPLETADO','FALLIDO','REEMBOLSADO') NOT NULL DEFAULT 'PENDIENTE',importe DECIMAL(10,2) NOT NULL CHECK(importe>=0),referencia_pago VARCHAR(120) UNIQUE,fecha_pago DATETIME,FOREIGN KEY(pedido_id) REFERENCES Pedido(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE Favorito(usuario_id BIGINT NOT NULL,carta_externa_id VARCHAR(100) NOT NULL,fecha_agregado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(usuario_id,carta_externa_id),FOREIGN KEY(usuario_id) REFERENCES Usuario(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE Incidencia(id BIGINT AUTO_INCREMENT PRIMARY KEY,pedido_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,descripcion TEXT NOT NULL,estado ENUM('ABIERTA','EN_REVISION','RESUELTA','CERRADA') NOT NULL DEFAULT 'ABIERTA',fecha_incidencia DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fecha_resolucion DATETIME,CHECK(fecha_resolucion IS NULL OR fecha_resolucion>=fecha_incidencia),FOREIGN KEY(pedido_id) REFERENCES Pedido(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES Usuario(id)) ENGINE=InnoDB;
CREATE INDEX idx_producto_carta ON Producto(carta_externa_id);CREATE INDEX idx_pedido_comprador ON Pedido(comprador_id);CREATE INDEX idx_pago_pedido ON Pago(pedido_id);
